// CTRL 位位置：与下方写动作块 wdata[1]/wdata[4]/wdata[5] 的译码共用
localparam CTRL_BIT_SOFT_RST = 1;
localparam CTRL_BIT_CLR_CNT  = 4;
localparam CTRL_BIT_CLR_FIFO = 5;
localparam [31:0] CTRL_SELFCLR_MASK = (32'h1 << CTRL_BIT_SOFT_RST)
                                    | (32'h1 << CTRL_BIT_CLR_CNT)
                                    | (32'h1 << CTRL_BIT_CLR_FIFO);

wire [31:0] ctrl_selfclear_mask = wstrb[0] ? CTRL_SELFCLR_MASK : 32'h0000_0000;
